const DRY_RUN = true; // Obligatorio hasta QC y OK de Pablo.
const ENVIO_ACTIVO = false;
const LIMITE = 40;
const TIPOS = new Set(['contacto','calculadora','curso','video','lead']);

function diasEntre(fecha, ahora) {
  const a = new Date(fecha);
  if (isNaN(a)) return -1;
  const d0 = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
  const d1 = Date.UTC(ahora.getFullYear(), ahora.getMonth(), ahora.getDate());
  return Math.floor((d1 - d0) / 86400000);
}

const ahora = new Date();
const filas = items.map(i => i.json);
const porEmail = {};
for (const rec of filas) {
  const email = String(rec.email || '').trim().toLowerCase();
  const tipo = String(rec.tipo || '').trim();
  if (!email || !email.includes('@') || !TIPOS.has(tipo)) continue;
  if (!porEmail[email]) porEmail[email] = { baja: false, dia0: false, dia3: false, pendientes: [] };
  const g = porEmail[email];
  if (String(rec.baja || '').trim()) g.baja = true;
  if (String(rec.dia0_enviado || '').trim()) g.dia0 = true;
  if (String(rec.dia3_enviado || '').trim()) g.dia3 = true;
  if (String(rec.token_baja || '').trim()) g.pendientes.push(rec);
}

const salidas = [];
let enviados = 0;
for (const [email, g] of Object.entries(porEmail)) {
  if (g.baja || !g.pendientes.length) continue;
  g.pendientes.sort((a,b) => new Date(a.fecha) - new Date(b.fecha));
  const base = g.pendientes[0];
  const dias = diasEntre(base.fecha, ahora);
  const cuales = [];
  if (!g.dia0 && dias >= 0) cuales.push(0);
  if (!g.dia3 && dias >= 3) cuales.push(3);
  for (const dia of cuales) {
    if (enviados >= LIMITE) break;
    const tema = String(base.tema || '').trim() || 'empezar';
    salidas.push({
      json: {
        email: base.email,
        nombre: base.nombre || '',
        tipo: base.tipo,
        tema,
        token_baja: base.token_baja,
        dia,
        row_number: base.row_number,
        DRY_RUN,
        ENVIO_ACTIVO,
        enviar: ENVIO_ACTIVO === true && DRY_RUN === false,
        marca: (DRY_RUN || !ENVIO_ACTIVO) ? ('DRY_RUN ' + ahora.toISOString()) : ahora.toISOString()
      }
    });
    enviados++;
  }
}
return salidas;
